mapper.sql:
WHERE 1=1
AND (A.PRD_NM LIKE CONCAT('%', #{searchKeyword}, '%') OR A.PRD_CD LIKE CONCAT('%', #{searchKeyword}, '%'))
AND A.PRD_STAT_CD = #{prdStatCd}

mapper.select:
/* PrdMngSQL.selectPrdMngListCnt */
SELECT COUNT(*)
FROM TB_PRD_MST A

mapper.insert:
/* PrdMngSQL.insertPrdMst */
INSERT INTO TB_PRD_MST (
	PRD_CD, PRD_NM, SMPL_DESC, PRD_STAT_CD, DELV_TP_CD,
	L_CAT_CD, M_CAT_CD, S_CAT_CD,
	STOCK_QTY
) VALUES (
	#{prdCd}, #{prdNm}, #{smplDesc}, #{prdStatCd}, #{delvTpCd},
	#{lCatCd}, #{mCatCd}, #{sCatCd},
	#{stockQty}
)

/* PrdMngSQL.insertPrdPrc */
INSERT INTO TB_PRD_PRC (
	PRD_CD, SALE_PRC, CARD_DISC_PRC, CASH_DISC_PRC
) VALUES (
	#{prdCd}, #{salePrc}, #{cardDiscPrc}, #{cashDiscPrc}
)

/* PrdMngSQL.insertPrdImg */
INSERT INTO TB_PRD_IMG (
	PRD_CD, IMG_PATH, IMG_NAME, IMG_TP_CD, SORT_SEQ
) VALUES (
	#{prdCd}, #{imgPath}, #{imgName}, '10', 1
)

mapper.delete:
/* PrdMngSQL.deletePrdImg */
DELETE FROM TB_PRD_IMG
WHERE PRD_CD = #{prdCd} AND IMG_TP_CD = '10'

mapper.insert:
/* PrdMngSQL.insertPrdDtlImg */
INSERT INTO TB_PRD_IMG (
	PRD_CD, IMG_PATH, IMG_NAME, IMG_TP_CD, SORT_SEQ
) VALUES (
	#{prdCd}, #{imgPath}, #{imgName}, '20', #{sortSeq}
)

mapper.delete:
/* PrdMngSQL.deletePrdDtlImg */
DELETE FROM TB_PRD_IMG
WHERE PRD_CD = #{prdCd} AND IMG_TP_CD = '20'

mapper.update:
/* PrdMngSQL.updatePrdPrc */
UPDATE TB_PRD_PRC SET
	SALE_PRC = #{salePrc},
	CARD_DISC_PRC = #{cardDiscPrc},
	CASH_DISC_PRC = #{cashDiscPrc}
WHERE PRD_CD = #{prdCd}

/* PrdMngSQL.updatePrdStat */
UPDATE TB_PRD_MST SET
	PRD_STAT_CD = #{prdStatCd},
	UPD_DT = CURRENT_TIMESTAMP
WHERE PRD_CD = #{prdCd}
